import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import {
  Box,
  Typography,
  TextField,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableContainer,
  TableRow,
  Paper,
  IconButton,
  Card,
  CardContent,
  Grid,
  InputAdornment,
  Avatar,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Divider,
  Badge,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Collapse,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
} from "@mui/material";
import {
  Search,
  FilterList,
  Notifications,
  Circle,
  CheckCircle,
  Error,
  Chat,
  Delete,
  Warning,
  Visibility,
} from "@mui/icons-material";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";

const AdminDashboard = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [tickets, setTickets] = useState([]);
  const [users, setUsers] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [notificationCount, setNotificationCount] = useState(0);
  const [filters, setFilters] = useState({
    department_id: "",
    location_id: "",
    priority: "",
    status: "",
  });
  const [filterOpen, setFilterOpen] = useState(false);
  const [departments, setDepartments] = useState([]);
  const [locations, setLocations] = useState([]);
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [ticketDetails, setTicketDetails] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [loadingDetails, setLoadingDetails] = useState(false);
  const [noDataMessage, setNoDataMessage] = useState("No Data Available");
  const navigate = useNavigate();
  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  useEffect(() => {
    const fetchLocationsAndDepartments = async () => {
      if (!token) {
        console.error("Authentication token is missing");
        return;
      }

      try {
        const [locationsResponse, departmentsResponse] = await Promise.all([
          apiRequest({ ...API.locationsList }),
          apiRequest({ ...API.departmentsList }),
        ]);

        setLocations(locationsResponse?.data || []);
        setDepartments(departmentsResponse?.data || []);
      } catch (error) {
        setLocations([]);
        setDepartments([]);

        console.error("Error fetching filter data:", error);
      }
    };
    if (token) fetchLocationsAndDepartments();
  }, [token]);

  // useEffect(() => {
  //   const fetchTickets = async () => {
  //     try {
  //       const response = await axios.get(
  //         "https://support.mcdonalds.mu/api/admin/ticket/list?paginate=true",
  //         { headers: { Authorization: `Bearer ${token}` } }
  //       );
  //       if (response.data.success) {
  //         setTickets(response.data.data.data);
  //       }
  //     } catch (error) {
  //       console.error("Error fetching tickets:", error);
  //     }
  //   };
  //   if (token) fetchTickets();
  // }, [token]);

  useEffect(() => {
    const fetchTickets = async () => {
      if (!token) {
        console.error("Authentication token is missing");
        return;
      }

      try {
        const response = await apiRequest({
          ...API.ticketList,

          params: {
            paginate: true,

            ...(filters.department_id && {
              department_id: filters.department_id,
            }),

            ...(filters.location_id && {
              location_id: filters.location_id,
            }),

            ...(filters.priority && {
              priority: filters.priority,
            }),

            ...(filters.status && {
              status: filters.status,
            }),
          },
        });

        if (response.success) {
          const ticketsData = response?.data?.data || [];

          setTickets(ticketsData);

          if (ticketsData.length === 0) {
            setNoDataMessage("No tickets found for the selected filters");
          } else {
            setNoDataMessage("");
          }
        } else {
          setTickets([]);

          if (
            response?.message === "No data found." &&
            response?.data?.error === "No data found"
          ) {
            setNoDataMessage("No tickets found for the selected filters");
          } else {
            setNoDataMessage("Failed to fetch tickets");
          }

          console.error("Error fetching tickets:", response?.message);
        }
      } catch (error) {
        setTickets([]);

        setNoDataMessage(
          error?.message === "No data found"
            ? "No tickets found for the selected filters"
            : "Failed to fetch tickets",
        );

        console.error("Error fetching tickets:", error);
      }
    };
    if (token) fetchTickets();
  }, [token, filters]);

  // Fetch Users
  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const response = await apiRequest({
          ...API.userList,

          params: {
            paginate: true,
          },
        });

        if (response.success) {
          // Limit to 6 users
          setUsers(response?.data?.data?.slice(0, 6) || []);
        }
      } catch (error) {
        console.error("Error fetching users:", error);
      }
    };
    if (token) fetchUsers();
  }, [token]);

  // Fetch Notifications
  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const response = await apiRequest({
          ...API.myNotifications,

          params: {
            paginate: true,
          },
        });

        if (response.success) {
          setNotifications(response?.data?.data || []);
          setNotificationCount(response?.data?.total || 0);
        }
      } catch (error) {
        console.error("Error fetching notifications:", error);
      }
    };
    if (token) fetchNotifications();
  }, [token]);

  const fetchTicketDetails = async (ticketId) => {
    setLoadingDetails(true);
    try {
      const response = await apiRequest({
        ...API.ticketDetails(ticketId),
      });
      if (response.success) {
        setTicketDetails(response.data);
      } else {
        setTicketDetails(null);
      }
    } catch (error) {
      console.error("Error fetching ticket details:", error);
      setTicketDetails(null);
    } finally {
      setLoadingDetails(false);
    }
  };

  const handleViewTicket = (ticket) => {
    setSelectedTicket(ticket);
    setDialogOpen(true);
    fetchTicketDetails(ticket.id);
  };

  const handleDialogClose = () => {
    setDialogOpen(false);
    setSelectedTicket(null);
    setTicketDetails(null);
  };
  const getPriorityColor = (priority) => {
    switch (priority) {
      case "High":
        return "#f44336";
      case "Medium":
        return "#ff9800";
      case "Low":
        return "#4caf50";
      default:
        return "#666666";
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "In progress":
        return "#ff9800";
      case "Resolved":
        return "#4caf50";
      case "Pending":
      case "New":
        return "#f44336";
      default:
        return "#666666";
    }
  };

  const getNotificationIcon = (trigger_event) => {
    switch (trigger_event) {
      case "Ticket Created":
        return <CheckCircle sx={{ fontSize: { xs: 16, sm: 18 } }} />;
      case "Ticket Assigned":
        return <Warning sx={{ fontSize: { xs: 16, sm: 18 } }} />;
      default:
        return <Error sx={{ fontSize: { xs: 16, sm: 18 } }} />;
    }
  };

  const getNotificationColor = (trigger_event) => {
    switch (trigger_event) {
      case "Ticket Created":
        return "#4caf50";
      case "Ticket Assigned":
        return "#ff9800";
      default:
        return "#f44336";
    }
  };
  const handleFilterChange = (name, value) => {
    setFilters((prev) => ({ ...prev, [name]: value }));
  };

  const clearFilters = () => {
    setFilters({
      department_id: "",
      location_id: "",
      priority: "",
      status: "",
    });
    setFilterOpen(false);
  };

  return (
    <Grid
      container
      rowSpacing={{ xs: 1, sm: 2, md: 2 }}
      columnSpacing={{ xs: 1, sm: 2, md: 2 }}
    >
      {/* Header with Search */}
      <Grid size={{ xs: 12, sm: 12, md: 12, lg: 12, xl: 12 }}>
        <Box
          sx={{
            display: "flex",
            flexDirection: { xs: "column", sm: "row" },
            justifyContent: "space-between",
            alignItems: { xs: "stretch", sm: "center" },
            mb: 3,
            gap: 2,
          }}
        >
          <Box sx={{ flexGrow: 1, maxWidth: { sm: 400 } }}>
            <TextField
              placeholder="Search dynamics..."
              variant="outlined"
              size="small"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              fullWidth
              sx={{
                "& .MuiOutlinedInput-root": {
                  borderRadius: 8,
                  backgroundColor: "#fff",
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                  "& input": {
                    padding: { xs: "6px 10px", sm: "8px 12px" },
                    fontSize: { xs: "0.75rem", sm: "0.875rem" },
                  },
                },
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search
                      sx={{ color: "#666", fontSize: { xs: 18, sm: 20 } }}
                    />
                  </InputAdornment>
                ),
              }}
            />
          </Box>
          <Box
            sx={{
              display: "flex",
              flexDirection: { xs: "row", sm: "row" },
              gap: 1,
              flexShrink: 0,
              alignItems: "center",
              justifyContent: { xs: "space-between", sm: "flex-end" },
            }}
          >
            <Button
              variant="outlined"
              size="small"
              startIcon={<FilterList sx={{ fontSize: { xs: 16, sm: 18 } }} />}
              onClick={() => setFilterOpen(!filterOpen)}
              sx={{
                borderColor: "#e0e0e0",
                color: "#333",
                borderRadius: 8,
                padding: { xs: "4px 8px", sm: "6px 12px" },
                textTransform: "none",
                fontWeight: 500,
                "&:hover": {
                  borderColor: "#bdbdbd",
                  backgroundColor: "rgba(0, 0, 0, 0.04)",
                },
              }}
              aria-label="toggle filter panel"
            >
              Filter
            </Button>
          </Box>
        </Box>

        <Collapse in={filterOpen}>
          <Paper
            sx={{
              p: 3,
              mb: 3,
              borderRadius: 3,
              bgcolor: "#f8f9fa",
              boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
            }}
          >
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6} md={3}>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel id="department-filter-label" shrink={true}>
                    Department
                  </InputLabel>
                  <Select
                    labelId="department-filter-label"
                    value={filters.department_id}
                    onChange={(e) =>
                      handleFilterChange("department_id", e.target.value)
                    }
                    label="Department"
                    displayEmpty
                    renderValue={(selected) =>
                      selected
                        ? departments.find((d) => d.id === selected)?.name ||
                          "All Departments"
                        : "All Departments"
                    }
                    sx={{
                      borderRadius: 8,
                      "& .MuiSelect-select": {
                        fontSize: { xs: "0.75rem", sm: "0.875rem" },
                      },
                      "& fieldset": { borderColor: "#e0e0e0" },
                      "&:hover fieldset": { borderColor: "#4CAF50" },
                      "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                    }}
                  >
                    <MenuItem value="">All Departments</MenuItem>
                    {departments.map((dept) => (
                      <MenuItem key={dept.id} value={dept.id}>
                        {dept.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel id="location-filter-label" shrink={true}>
                    Location
                  </InputLabel>
                  <Select
                    labelId="location-filter-label"
                    value={filters.location_id}
                    onChange={(e) =>
                      handleFilterChange("location_id", e.target.value)
                    }
                    label="Location"
                    displayEmpty
                    renderValue={(selected) =>
                      selected
                        ? locations.find((l) => l.id === selected)?.name ||
                          "All Locations"
                        : "All Locations"
                    }
                    sx={{
                      borderRadius: 8,
                      "& .MuiSelect-select": {
                        fontSize: { xs: "0.75rem", sm: "0.875rem" },
                      },
                      "& fieldset": { borderColor: "#e0e0e0" },
                      "&:hover fieldset": { borderColor: "#4CAF50" },
                      "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                    }}
                  >
                    <MenuItem value="">All Locations</MenuItem>
                    {locations.map((loc) => (
                      <MenuItem key={loc.id} value={loc.id}>
                        {loc.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel id="priority-filter-label" shrink={true}>
                    Priority
                  </InputLabel>
                  <Select
                    labelId="priority-filter-label"
                    value={filters.priority}
                    onChange={(e) =>
                      handleFilterChange("priority", e.target.value)
                    }
                    label="Priority"
                    displayEmpty
                    renderValue={(selected) => selected || "All Priorities"}
                    sx={{
                      borderRadius: 8,
                      "& .MuiSelect-select": {
                        fontSize: { xs: "0.75rem", sm: "0.875rem" },
                      },
                      "& fieldset": { borderColor: "#e0e0e0" },
                      "&:hover fieldset": { borderColor: "#4CAF50" },
                      "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                    }}
                  >
                    <MenuItem value="">All Priorities</MenuItem>
                    {["Low", "Medium", "High"].map((priority) => (
                      <MenuItem key={priority} value={priority}>
                        {priority}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel id="status-filter-label" shrink={true}>
                    Status
                  </InputLabel>
                  <Select
                    labelId="status-filter-label"
                    value={filters.status}
                    onChange={(e) =>
                      handleFilterChange("status", e.target.value)
                    }
                    label="Status"
                    displayEmpty
                    renderValue={(selected) => selected || "All Statuses"}
                    sx={{
                      borderRadius: 8,
                      "& .MuiSelect-select": {
                        fontSize: { xs: "0.75rem", sm: "0.875rem" },
                      },
                      "& fieldset": { borderColor: "#e0e0e0" },
                      "&:hover fieldset": { borderColor: "#4CAF50" },
                      "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                    }}
                  >
                    <MenuItem value="">All Statuses</MenuItem>
                    {["Pending", "New", "In progress", "Resolved"].map(
                      (status) => (
                        <MenuItem key={status} value={status}>
                          {status}
                        </MenuItem>
                      ),
                    )}
                  </Select>
                </FormControl>
              </Grid>
            </Grid>
            <Box
              sx={{
                display: "flex",
                justifyContent: "flex-end",
                mt: 2,
                gap: 1,
              }}
            >
              <Button
                variant="outlined"
                onClick={clearFilters}
                sx={{
                  borderColor: "#e0e0e0",
                  color: "#333",
                  textTransform: "none",
                  fontSize: { xs: "0.75rem", sm: "0.875rem" },
                  px: 3,
                  py: 1,
                  borderRadius: 8,
                  "&:hover": {
                    borderColor: "#bdbdbd",
                    bgcolor: "rgba(0,0,0,0.04)",
                  },
                }}
              >
                Clear Filters
              </Button>
              <Button
                variant="contained"
                onClick={() => setFilterOpen(false)}
                sx={{
                  bgcolor: "#4CAF50",
                  "&:hover": { bgcolor: "#388e3c" },
                  textTransform: "none",
                  fontSize: { xs: "0.75rem", sm: "0.875rem" },
                  px: 3,
                  py: 1,
                  borderRadius: 8,
                  boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                }}
              >
                Apply Filters
              </Button>
            </Box>
          </Paper>
        </Collapse>

        <Paper
          sx={{ overflow: "hidden", boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}
        >
          <TableContainer
            sx={{ maxWidth: "100%", overflowX: "auto" }}
            tabIndex={0}
          >
            <Table
              stickyHeader
              aria-label="tickets table"
              sx={{ minWidth: 650 }}
            >
              <TableHead>
                <TableRow sx={{ backgroundColor: "#f8f9fa" }}>
                  {[
                    { label: "ID" },
                    { label: "Title" },
                    { label: "Department" },
                    { label: "Location" },
                    { label: "Priority" },
                    { label: "Status" },
                    { label: "View" },
                  ].map((column) => (
                    <TableCell
                      key={column.label}
                      scope="col"
                      sx={{
                        fontWeight: 600,
                        backgroundColor: "#f8f9fa",
                        color: "#1f2937",
                        textOverflow:
                          column.label === "Title" ||
                          column.label === "Department" ||
                          column.label === "Location"
                            ? "ellipsis"
                            : "clip",
                        overflow:
                          column.label === "Title" ||
                          column.label === "Department" ||
                          column.label === "Location"
                            ? "hidden"
                            : "visible",
                        whiteSpace:
                          column.label === "Title" ||
                          column.label === "Department" ||
                          column.label === "Location"
                            ? "normal"
                            : "nowrap",
                      }}
                    >
                      {column.label}
                    </TableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {tickets.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} align="center">
                      <Typography
                        variant="body2"
                        sx={{ color: "#6b7280", py: 2 }}
                      >
                        {noDataMessage}
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  tickets &&
                  tickets.filter((ticket) =>
                    ticket.title
                      .toLowerCase()
                      .includes(searchQuery.toLowerCase()),
                  ).length !== 0 &&
                  tickets
                    .filter((ticket) =>
                      ticket.title
                        .toLowerCase()
                        .includes(searchQuery.toLowerCase()),
                    )
                    .map((ticket) => (
                      <TableRow
                        key={ticket.id}
                        hover
                        sx={{ "&:hover": { backgroundColor: "#f1f5f9" } }}
                      >
                        <TableCell scope="row">{ticket.id}</TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {ticket.title}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {ticket.department.name}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {ticket.location.name}
                        </TableCell>
                        <TableCell>
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "center",
                              gap: 0.5,
                            }}
                          >
                            <Circle
                              sx={{
                                fontSize: 8,
                                color: getPriorityColor(ticket.priority),
                              }}
                            />
                            <Typography
                              variant="body2"
                              sx={{
                                color: getPriorityColor(ticket.priority),
                              }}
                            >
                              {ticket.priority}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell>
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "center",
                              gap: 0.5,
                            }}
                          >
                            <Circle
                              sx={{
                                fontSize: 8,
                                color: getStatusColor(ticket.status),
                              }}
                            />
                            <Typography
                              variant="body2"
                              sx={{
                                color: getStatusColor(ticket.status),
                              }}
                            >
                              {ticket.status}
                            </Typography>
                          </Box>
                        </TableCell>
                        <TableCell
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          <IconButton
                            onClick={() => {
                              // handleViewTicket(ticket)
                              navigate(`/dashboard/tickets?id=${ticket.id}`);
                            }}
                            sx={{
                              color: "#43B02A",
                              "&:hover": { color: "#3a9c26" },
                            }}
                            aria-label={`view ticket ${ticket.id}`}
                          >
                            <Visibility fontSize="small" />
                          </IconButton>
                        </TableCell>
                      </TableRow>
                    ))
                )}
              </TableBody>
            </Table>
            {tickets.filter((ticket) =>
              ticket.title.toLowerCase().includes(searchQuery.toLowerCase()),
            ).length === 0 && (
              <Typography sx={{ textAlign: "center", py: 4 }}>
                {noDataMessage}
              </Typography>
            )}
          </TableContainer>
        </Paper>
      </Grid>
      {/* Ticket Details Dialog */}
      <Dialog
        open={dialogOpen}
        onClose={handleDialogClose}
        maxWidth="md"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            borderRadius: 3,
            background: "linear-gradient(145deg, #ffffff, #f5f7fa)",
            boxShadow: "0 12px 24px rgba(0,0,0,0.15)",
            overflow: "hidden",
            maxWidth: { xs: "90%", sm: "600px" },
            p: { xs: 1, sm: 2 },
          },
        }}
      >
        <DialogTitle
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 1,
            background: "linear-gradient(45deg, #43B02A 0%, #66BB6A 100%)",
            color: "#fff",
            fontWeight: 600,
            fontSize: { xs: "1.2rem", sm: "1.5rem" },
            p: 2,
            borderRadius: "12px 12px 0 0",
          }}
        >
          <Visibility sx={{ fontSize: { xs: 20, sm: 24 } }} />
          Ticket #{selectedTicket?.id || "N/A"}
        </DialogTitle>
        <DialogContent sx={{ p: { xs: 2, sm: 3 } }}>
          {loadingDetails ? (
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                minHeight: 200,
              }}
            >
              <CircularProgress size={40} sx={{ color: "#43B02A" }} />
            </Box>
          ) : ticketDetails ? (
            <Box sx={{ display: "flex", flexDirection: "column", gap: 2.5 }}>
              <Paper
                elevation={1}
                sx={{
                  p: 2,
                  borderRadius: 2,
                  backgroundColor: "#fafafa",
                  border: "1px solid #e0e0e0",
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 600,
                    color: "#1f2937",
                    mb: 2,
                    fontSize: { xs: "1rem", sm: "1.25rem" },
                  }}
                >
                  Ticket Information
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Title
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.title || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Priority
                    </Typography>
                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        gap: 0.5,
                      }}
                    >
                      <Circle
                        sx={{
                          fontSize: 8,
                          color: getPriorityColor(ticketDetails.priority),
                        }}
                      />
                      <Typography
                        variant="body1"
                        sx={{
                          fontWeight: 500,
                          color: getPriorityColor(ticketDetails.priority),
                          fontSize: { xs: "0.9rem", sm: "1rem" },
                        }}
                      >
                        {ticketDetails.priority || "N/A"}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Status
                    </Typography>
                    <Box
                      sx={{
                        display: "flex",
                        alignItems: "center",
                        gap: 0.5,
                      }}
                    >
                      <Circle
                        sx={{
                          fontSize: 8,
                          color: getStatusColor(ticketDetails.status),
                        }}
                      />
                      <Typography
                        variant="body1"
                        sx={{
                          fontWeight: 500,
                          color: getStatusColor(ticketDetails.status),
                          fontSize: { xs: "0.9rem", sm: "1rem" },
                        }}
                      >
                        {ticketDetails.status || "N/A"}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Reported By
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.submit_by?.name || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Department
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.department?.name || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Location
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.location?.name || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Description
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.description || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Issue
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.issue || "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Assigned To
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.assign_to?.name || "Unassigned"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Expected Resolution Time
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.expected_resolution_time
                        ? new Date(
                            ticketDetails.expected_resolution_time,
                          ).toLocaleString()
                        : "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Created At
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.created_at
                        ? new Date(ticketDetails.created_at).toLocaleString()
                        : "N/A"}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Typography
                      variant="subtitle2"
                      color="#666"
                      fontWeight={500}
                      sx={{ fontSize: { xs: "0.8rem", sm: "0.875rem" } }}
                    >
                      Updated At
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontWeight: 500,
                        color: "#1f2937",
                        fontSize: { xs: "0.9rem", sm: "1rem" },
                      }}
                    >
                      {ticketDetails.updated_at
                        ? new Date(ticketDetails.updated_at).toLocaleString()
                        : "N/A"}
                    </Typography>
                  </Grid>
                </Grid>
              </Paper>
              <Paper
                elevation={1}
                sx={{
                  p: 2,
                  borderRadius: 2,
                  backgroundColor: "#fafafa",
                  border: "1px solid #e0e0e0",
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 600,
                    color: "#1f2937",
                    mb: 2,
                    fontSize: { xs: "1rem", sm: "1.25rem" },
                  }}
                >
                  Comments
                </Typography>
                {ticketDetails.comment && ticketDetails.comment.length > 0 ? (
                  <Box sx={{ maxHeight: 250, overflowY: "auto" }}>
                    {ticketDetails.comment.map((comment) => (
                      <Paper
                        key={comment.id}
                        elevation={0}
                        sx={{
                          p: 1.5,
                          mb: 1,
                          borderRadius: 2,
                          backgroundColor: "#ffffff",
                          border: "1px solid #e0e0e0",
                          transition: "all 0.2s",
                          "&:hover": {
                            boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                          },
                        }}
                      >
                        <Box
                          sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            mb: 0.5,
                          }}
                        >
                          <Avatar
                            sx={{
                              width: { xs: 24, sm: 28 },
                              height: { xs: 24, sm: 28 },
                              bgcolor: "#43B02A",
                              fontSize: { xs: "0.75rem", sm: "0.875rem" },
                            }}
                          >
                            {comment.user?.name?.charAt(0) || "U"}
                          </Avatar>
                          <Typography
                            variant="body2"
                            sx={{
                              fontWeight: 600,
                              color: "#1f2937",
                              fontSize: { xs: "0.85rem", sm: "0.9rem" },
                            }}
                          >
                            {comment.user?.name || "Unknown"}
                          </Typography>
                        </Box>
                        <Typography
                          variant="body2"
                          sx={{
                            color: "#1f2937",
                            fontSize: { xs: "0.85rem", sm: "0.9rem" },
                            mb: 0.5,
                          }}
                        >
                          {comment.comment || "N/A"}
                        </Typography>
                        <Typography
                          variant="caption"
                          sx={{
                            color: "#6b7280",
                            fontSize: { xs: "0.7rem", sm: "0.75rem" },
                          }}
                        >
                          {comment.created_at
                            ? new Date(comment.created_at).toLocaleString()
                            : "N/A"}
                        </Typography>
                      </Paper>
                    ))}
                  </Box>
                ) : (
                  <Typography
                    variant="body2"
                    sx={{
                      color: "#6b7280",
                      textAlign: "center",
                      py: 2,
                      fontSize: { xs: "0.85rem", sm: "0.9rem" },
                    }}
                  >
                    No comments available
                  </Typography>
                )}
              </Paper>
            </Box>
          ) : (
            <Typography
              variant="body2"
              sx={{
                color: "#6b7280",
                textAlign: "center",
                py: 4,
                fontSize: { xs: "0.9rem", sm: "1rem" },
              }}
            >
              No Data Available
            </Typography>
          )}
        </DialogContent>
        <DialogActions sx={{ p: 2, justifyContent: "center" }}>
          <Button
            onClick={handleDialogClose}
            variant="contained"
            sx={{
              backgroundColor: "#43B02A",
              color: "#fff",
              borderRadius: 6,
              textTransform: "none",
              fontWeight: 500,
              fontSize: { xs: "0.85rem", sm: "0.9rem" },
              px: 3,
              "&:hover": {
                backgroundColor: "#3a9c26",
                boxShadow: "0 2px 8px rgba(67, 176, 42, 0.3)",
              },
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
      {/* Sidebar Cards */}
      <Grid size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
        <Card
          sx={{
            height: "100%",
            borderRadius: "15px",
            width: "100%",
            boxSizing: "border-box",
          }}
        >
          <CardContent sx={{ p: { xs: 1, sm: 2 } }}>
            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                mb: 2,
                flexDirection: { xs: "column", sm: "row" },
                gap: 1,
              }}
            >
              <Typography
                variant="h6"
                sx={{
                  fontWeight: 500,
                  color: "#1f2937",
                  fontSize: { xs: "1rem", sm: "1.25rem" },
                }}
              >
                User Management
              </Typography>
              <Box sx={{ display: "flex", gap: 1 }}>
                <Button
                  variant="contained"
                  size="small"
                  sx={{
                    backgroundColor: "#F97316",
                    "&:hover": { backgroundColor: "#E56A14" },
                    textTransform: "none",
                    padding: { xs: "4px 8px", sm: "6px 12px" },
                    borderRadius: 6,
                  }}
                  onClick={() => navigate("/dashboard/user-management")}
                  aria-label="view all users"
                >
                  View All
                </Button>
              </Box>
            </Box>
            <TableContainer sx={{ overflowX: "auto" }} tabIndex={0}>
              <Table aria-label="user management table" sx={{ minWidth: 500 }}>
                <TableHead>
                  <TableRow>
                    <TableCell
                      scope="col"
                      sx={{
                        fontWeight: 600,
                      }}
                    >
                      Name
                    </TableCell>
                    <TableCell
                      scope="col"
                      sx={{
                        fontWeight: 600,
                      }}
                    >
                      Email
                    </TableCell>
                    <TableCell
                      scope="col"
                      sx={{
                        fontWeight: 600,
                      }}
                    >
                      Department
                    </TableCell>
                    <TableCell
                      scope="col"
                      sx={{
                        fontWeight: 600,
                      }}
                    >
                      Role
                    </TableCell>
                    {/* <TableCell
                      scope="col"
                      sx={{
                        fontWeight: 600,
                      }}
                    >
                      Actions
                    </TableCell> */}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {users.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        <Typography
                          variant="body2"
                          sx={{ color: "#6b7280", py: 2 }}
                        >
                          No Data Available
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ) : (
                    users.map((user) => (
                      <TableRow key={user.id}>
                        <TableCell
                          scope="row"
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {user.name}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {user.email}
                        </TableCell>
                        <TableCell
                          sx={{
                            textOverflow: "ellipsis",
                            overflow: "hidden",
                            whiteSpace: "normal",
                          }}
                        >
                          {user.department_id ? "Cash counter" : "N/A"}
                        </TableCell>
                        <TableCell
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          {user.role.charAt(0).toUpperCase() +
                            user.role.slice(1)}
                        </TableCell>
                        <TableCell
                          sx={{
                            whiteSpace: "nowrap",
                          }}
                        >
                          {/* <Button
                            variant="contained"
                            size="small"
                            sx={{
                              backgroundColor: "#43B02A",
                              "&:hover": { backgroundColor: "#3A8F22" },
                              fontSize: { xs: "0.55rem", sm: "0.65rem" },
                              padding: { xs: "2px 8px", sm: "3px 10px" },
                              borderRadius: 6,
                            }}
                            aria-label={`edit user ${user.name}`}
                          >
                            Edit
                          </Button> */}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </CardContent>
        </Card>
      </Grid>

      <Grid size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
        <Card
          sx={{
            height: "100%",
            borderRadius: "15px",
            width: "100%",
            boxSizing: "border-box",
          }}
        >
          <CardContent sx={{ p: { xs: 1, sm: 2 } }}>
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                mb: 2,
                flexDirection: { xs: "column", sm: "row" },
                gap: 1,
              }}
            >
              <Typography
                variant="h6"
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 2,
                  color: "#1f2937",
                  fontWeight: 500,
                  fontSize: { xs: "1rem", sm: "1.25rem" },
                }}
              >
                {/* <Badge
                  badgeContent={notificationCount}
                  color="error"
                  sx={{
                    "& .MuiBadge-badge": {
                      fontSize: { xs: "0.55rem", sm: "0.65rem" },
                      height: { xs: 16, sm: 18 },
                      minWidth: { xs: 16, sm: 18 },
                      bgcolor: "#DA291C",
                    },
                  }}
                >
                  <Notifications sx={{ fontSize: { xs: 18, sm: 20 } }} />
                </Badge> */}
                <Notifications sx={{ fontSize: { xs: 18, sm: 20 } }} />
                Notifications
              </Typography>
              <Box sx={{ display: "flex", gap: 1 }}>
                {/* <Button
                  variant="outlined"
                  startIcon={
                    <FilterList sx={{ fontSize: { xs: 16, sm: 18 } }} />
                  }
                  size="small"
                  sx={{
                    borderColor: "#e0e0e0",
                    color: "#333",
                    "&:hover": { backgroundColor: "rgba(0, 0, 0, 0.04)" },
                    padding: { xs: "4px 8px", sm: "6px 12px" },
                    borderRadius: 6,
                    textTransform: "none",
                  }}
                  aria-label="filter notifications"
                >
                  Filter
                </Button> */}
                <Button
                  variant="contained"
                  size="small"
                  sx={{
                    backgroundColor: "#F97316",
                    "&:hover": { backgroundColor: "#E56A14" },
                    textTransform: "none",
                    padding: { xs: "4px 8px", sm: "6px 12px" },
                    borderRadius: 6,
                  }}
                  onClick={() => navigate("/dashboard/notifications")}
                  aria-label="view all notifications"
                >
                  View All
                </Button>
              </Box>
            </Box>
            <List sx={{ maxHeight: 300, overflowY: "auto" }}>
              {notifications.length === 0 ? (
                <ListItem>
                  <ListItemText
                    primary={
                      <Typography
                        variant="body2"
                        sx={{
                          color: "#6b7280",
                          textAlign: "center",
                          py: 2,
                        }}
                      >
                        No Data Available
                      </Typography>
                    }
                  />
                </ListItem>
              ) : (
                notifications.map((notification, index) => (
                  <React.Fragment key={notification.id}>
                    <ListItem
                      sx={{
                        "&:hover": { backgroundColor: "#f1f5f9" },
                        borderRadius: 6,
                        mb: 1,
                        flexDirection: { xs: "column", sm: "row" },
                        alignItems: { xs: "flex-start", sm: "center" },
                        gap: { xs: 1, sm: 2 },
                        py: { xs: 0.5, sm: 1 },
                      }}
                    >
                      <ListItemIcon>
                        <Avatar
                          sx={{
                            bgcolor: getNotificationColor(
                              notification.trigger_event,
                            ),
                            width: { xs: 24, sm: 28 },
                            height: { xs: 24, sm: 28 },
                          }}
                        >
                          {getNotificationIcon(notification.trigger_event)}
                        </Avatar>
                      </ListItemIcon>
                      <ListItemText
                        primary={
                          <Typography
                            variant="body2"
                            sx={{
                              fontWeight: 600,
                              color: "#1f2937",
                              fontSize: { xs: "0.75rem", sm: "0.875rem" },
                            }}
                          >
                            {notification.title}
                          </Typography>
                        }
                        secondary={
                          <>
                            <Typography
                              variant="caption"
                              display="block"
                              sx={{
                                color: "#6b7280",
                              }}
                            >
                              {notification.message}
                            </Typography>
                            <Typography
                              variant="caption"
                              sx={{
                                color: "#6b7280",
                              }}
                            >
                              {new Date(
                                notification.created_at,
                              ).toLocaleString()}
                            </Typography>
                          </>
                        }
                      />
                      {/* <Box
                        sx={{ display: "flex", mt: { xs: 1, sm: 0 }, gap: 0.5 }}
                      >
                        <IconButton
                          size="small"
                          sx={{
                            color: "#6b7280",
                            "&:hover": { color: "#1f2937" },
                            padding: { xs: 0.5, sm: 1 },
                          }}
                          aria-label={`comment on notification ${notification.title}`}
                        >
                          <Chat sx={{ fontSize: { xs: 16, sm: 18 } }} />
                        </IconButton>
                        <IconButton
                          size="small"
                          sx={{
                            color: "#6b7280",
                            "&:hover": { color: "#1f2937" },
                            padding: { xs: 0.5, sm: 1 },
                          }}
                          aria-label={`delete notification ${notification.title}`}
                        >
                          <Delete sx={{ fontSize: { xs: 16, sm: 18 } }} />
                        </IconButton>
                      </Box> */}
                    </ListItem>
                    {index < notifications.length - 1 && (
                      <Divider sx={{ bgcolor: "#e0e0e0" }} />
                    )}
                  </React.Fragment>
                ))
              )}
            </List>
          </CardContent>
        </Card>
      </Grid>
    </Grid>
  );
};

export default AdminDashboard;
